/* From Uiverse.io by gharsh11032000 - Tags: red, button, hover, shake */
.__UIV_SCOPE__ .button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 15px 20px;
  background-color: #212121;
  border: none;
  font: inherit;
  color: #e8e8e8;
  font-size: 20px;
  font-weight: 600;
  border-radius: 50px;
  cursor: not-allowed;
  overflow: hidden;
  transition: all 0.3s ease cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .button span {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .button::before {
  position: absolute;
  content: '';
  width: 100%;
  height: 100%;
  translate: 0 105%;
  background-color: #F53844;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .button svg {
  width: 32px;
  height: 32px;
  fill: #F53844;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .button:hover {
  animation: shake 0.2s linear 1;
}

.__UIV_SCOPE__ .button:hover::before {
  translate: 0 0;
}

.__UIV_SCOPE__ .button:hover svg {
  fill: #e8e8e8;
}

@keyframes shake {
  0% {
    rotate: 0deg;
  }

  33% {
    rotate: 10deg;
  }

  66% {
    rotate: -10deg;
  }

  100% {
    rotate: 10deg;
  }
}
